sections.sandboxCode:
// Interactive reactivity example
const { ui, createState } = PotokSDK;

const state = createState({
  clicks: 0,
  lastClicked: "Never"
});

function draw() {
  ui.render(
    Card()
      .title("Click counter")
      .child(
        VStack()
          .spacing(12)
          .child(Text("Clicks recorded: " + state.clicks).bold(true).size("lg"))
          .child(Text("Last click: " + state.lastClicked).variant("secondary"))
          .child(
            Button("Click!")
              .variant("primary")
              .onClick(() => {
                state.clicks++;
                state.lastClicked = new Date().toLocaleTimeString();
              })
          )
      )
  );
}

state.$subscribe(draw);
draw();

// Network data loading example
const { ui, http, createState } = PotokSDK;

const state = createState({
  loading: true,
  todoTitle: "",
  error: null
});

async function loadData() {
  try {
    const res = await http.get("https://jsonplaceholder.typicode.com/todos/1");
    state.todoTitle = res.data.title;
    state.loading = false;
  } catch (err) {
    state.error = err.message;
    state.loading = false;
  }
}

function render() {
  ui.render(
    Card()
      .title("Network loading")
      .child(
        VStack()
          .spacing(12)
          .child(
            state.loading 
              ? LoadingSpinner().message("Loading TODO from server...")
              : Text(state.error ? "Error: " + state.error : "Task from server: " + state.todoTitle)
          )
          .child(
            Button("Reload")
              .onClick(() => {
                state.loading = true;
                loadData();
              })
          )
      )
  );
}

state.$subscribe(render);
render();
loadData();

// Save and load settings example
const { ui, storage, createState } = PotokSDK;

const state = createState({
  savedValue: "Nothing saved",
  inputValue: ""
});

async function initStorage() {
  const saved = await storage.local.getItem("user_custom_note");
  if (saved) {
    state.savedValue = saved;
  }
}

function render() {
  ui.render(
    Card()
      .title("Local storage")
      .child(
        VStack()
          .spacing(12)
          .child(Text("Saved in DB: " + state.savedValue).bold(true))
          .child(
            Input("note-input")
              .label("New entry")
              .value(state.inputValue)
              .onChange((val) => state.inputValue = val)
          )
          .child(
            Button("Save to DB")
              .variant("primary")
              .onClick(async () => {
                await storage.local.setItem("user_custom_note", state.inputValue);
                state.savedValue = state.inputValue;
                ui.showHUD("success", "Value saved successfully!");
              })
          )
      )
  );
}

state.$subscribe(render);
render();
initStorage();

